export function searchLibraries({ query = '', category = 'All libraries', language = 'All languages', saved = null, project = '' } = {}) {
  const words = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  const projectWords = project.toLowerCase().match(/[a-z]+/g)?.filter(w => w.length > 2 && !['the', 'and', 'for', 'with', 'want', 'build', 'project', 'need', 'that'].includes(w)) || [];
  return libraries.filter(lib => {
    const text = [lib.name, lib.description, lib.category, ...lib.tags, lib.keywords].join(' ').toLowerCase();
    return words.every(word => text.includes(word)) && (category === 'All libraries' || lib.category === category) && (language === 'All languages' || lib.tags.includes(language)) && (!saved || saved.includes(lib.id));
  }).map(lib => ({ ...lib, score: projectWords.reduce((n, word) => n + (lib.keywords.includes(word) ? 3 : 0) + ([lib.name, lib.description, ...lib.tags].join(' ').toLowerCase().includes(word) ? 1 : 0), 0) })).filter(lib => !projectWords.length || lib.score > 0).sort((a, b) => b.score - a.score);
}
